macro_rules! deps {
    () => {
        NFA!();
        PikeVM!();
        Start!();
        DFA!();
        Match!();
    };
}

macro_rules! Look {
    () => {
        deps!();
        # [doc = " A look-around assertion."] # [doc = ""] # [doc = " An assertion matches at a position between characters in a haystack."] # [doc = " Namely, it does not actually \"consume\" any input as most parts of a regular"] # [doc = " expression do. Assertions are a way of stating that some property must be"] # [doc = " true at a particular point during matching."] # [doc = ""] # [doc = " For example, `(?m)^[a-z]+$` is a pattern that:"] # [doc = ""] # [doc = " * Scans the haystack for a position at which `(?m:^)` is satisfied. That"] # [doc = " occurs at either the beginning of the haystack, or immediately following"] # [doc = " a `\\n` character."] # [doc = " * Looks for one or more occurrences of `[a-z]`."] # [doc = " * Once `[a-z]+` has matched as much as it can, an overall match is only"] # [doc = " reported when `[a-z]+` stops just before a `\\n`."] # [doc = ""] # [doc = " So in this case, `abc` and `\\nabc\\n` match, but `\\nabc1\\n` does not."] # [doc = ""] # [doc = " Assertions are also called \"look-around,\" \"look-behind\" and \"look-ahead.\""] # [doc = " Specifically, some assertions are look-behind (like `^`), other assertions"] # [doc = " are look-ahead (like `$`) and yet other assertions are both look-ahead and"] # [doc = " look-behind (like `\\b`)."] # [doc = ""] # [doc = " # Assertions in an NFA"] # [doc = ""] # [doc = " An assertion in a [`thompson::NFA`](crate::nfa::thompson::NFA) can be"] # [doc = " thought of as a conditional epsilon transition. That is, a matching engine"] # [doc = " like the [`PikeVM`](crate::nfa::thompson::pikevm::PikeVM) only permits"] # [doc = " moving through conditional epsilon transitions when their condition"] # [doc = " is satisfied at whatever position the `PikeVM` is currently at in the"] # [doc = " haystack."] # [doc = ""] # [doc = " How assertions are handled in a `DFA` is trickier, since a DFA does not"] # [doc = " have epsilon transitions at all. In this case, they are compiled into the"] # [doc = " automaton itself, at the expense of more states than what would be required"] # [doc = " without an assertion."] # [derive (Clone , Copy , Debug , Eq , PartialEq)] pub enum Look { # [doc = " Match the beginning of text. Specifically, this matches at the starting"] # [doc = " position of the input."] Start = 1 << 0 , # [doc = " Match the end of text. Specifically, this matches at the ending"] # [doc = " position of the input."] End = 1 << 1 , # [doc = " Match the beginning of a line or the beginning of text. Specifically,"] # [doc = " this matches at the starting position of the input, or at the position"] # [doc = " immediately following a `\\n` character."] StartLF = 1 << 2 , # [doc = " Match the end of a line or the end of text. Specifically, this matches"] # [doc = " at the end position of the input, or at the position immediately"] # [doc = " preceding a `\\n` character."] EndLF = 1 << 3 , # [doc = " Match the beginning of a line or the beginning of text. Specifically,"] # [doc = " this matches at the starting position of the input, or at the position"] # [doc = " immediately following either a `\\r` or `\\n` character, but never after"] # [doc = " a `\\r` when a `\\n` follows."] StartCRLF = 1 << 4 , # [doc = " Match the end of a line or the end of text. Specifically, this matches"] # [doc = " at the end position of the input, or at the position immediately"] # [doc = " preceding a `\\r` or `\\n` character, but never before a `\\n` when a `\\r`"] # [doc = " precedes it."] EndCRLF = 1 << 5 , # [doc = " Match an ASCII-only word boundary. That is, this matches a position"] # [doc = " where the left adjacent character and right adjacent character"] # [doc = " correspond to a word and non-word or a non-word and word character."] WordAscii = 1 << 6 , # [doc = " Match an ASCII-only negation of a word boundary."] WordAsciiNegate = 1 << 7 , # [doc = " Match a Unicode-aware word boundary. That is, this matches a position"] # [doc = " where the left adjacent character and right adjacent character"] # [doc = " correspond to a word and non-word or a non-word and word character."] WordUnicode = 1 << 8 , # [doc = " Match a Unicode-aware negation of a word boundary."] WordUnicodeNegate = 1 << 9 , # [doc = " Match the start of an ASCII-only word boundary. That is, this matches a"] # [doc = " position at either the beginning of the haystack or where the previous"] # [doc = " character is not a word character and the following character is a word"] # [doc = " character."] WordStartAscii = 1 << 10 , # [doc = " Match the end of an ASCII-only word boundary. That is, this matches"] # [doc = " a position at either the end of the haystack or where the previous"] # [doc = " character is a word character and the following character is not a word"] # [doc = " character."] WordEndAscii = 1 << 11 , # [doc = " Match the start of a Unicode word boundary. That is, this matches a"] # [doc = " position at either the beginning of the haystack or where the previous"] # [doc = " character is not a word character and the following character is a word"] # [doc = " character."] WordStartUnicode = 1 << 12 , # [doc = " Match the end of a Unicode word boundary. That is, this matches a"] # [doc = " position at either the end of the haystack or where the previous"] # [doc = " character is a word character and the following character is not a word"] # [doc = " character."] WordEndUnicode = 1 << 13 , # [doc = " Match the start half of an ASCII-only word boundary. That is, this"] # [doc = " matches a position at either the beginning of the haystack or where the"] # [doc = " previous character is not a word character."] WordStartHalfAscii = 1 << 14 , # [doc = " Match the end half of an ASCII-only word boundary. That is, this"] # [doc = " matches a position at either the end of the haystack or where the"] # [doc = " following character is not a word character."] WordEndHalfAscii = 1 << 15 , # [doc = " Match the start half of a Unicode word boundary. That is, this matches"] # [doc = " a position at either the beginning of the haystack or where the"] # [doc = " previous character is not a word character."] WordStartHalfUnicode = 1 << 16 , # [doc = " Match the end half of a Unicode word boundary. That is, this matches"] # [doc = " a position at either the end of the haystack or where the following"] # [doc = " character is not a word character."] WordEndHalfUnicode = 1 << 17 , }
    };
}

Look!();